descriptor.templateCss:
.mf-root { height: 100%; -webkit-user-select: none; user-select: none; }
.mf-card {
  --t: #E8E6E1; --m: #8A8F94; --d: #6a6e72; --c: #D9694F; --dot: rgba(255, 255, 255, .28); --line: rgba(255, 255, 255, .12);
  height: 100%; box-sizing: border-box; padding: 10px 18px; display: flex; flex-direction: column; justify-content: center; gap: 10px;
  font-family: 'IBM Plex Sans', Roboto, sans-serif; color: var(--t);
}
.mf-head { display: flex; justify-content: space-between; align-items: baseline; gap: 8px; }
.mf-title { font-size: 12px; font-weight: 400; letter-spacing: .14em; text-transform: uppercase; color: var(--m); }
.mf-status { font-size: 12px; color: var(--m); white-space: nowrap; }
.mf-diagram { display: flex; align-items: flex-start; }
.mf-node { flex: none; width: 72px; display: flex; flex-direction: column; align-items: center; gap: 8px; padding-top: 19px; }
.mf-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--dot); transition: background .4s, box-shadow .4s; }
.mf-node.active .mf-dot { background: var(--flow); box-shadow: 0 0 8px var(--flow); }
.mf-dot { position: relative; }
.mf-node.active .mf-dot::after { content: ''; position: absolute; inset: -1px; border-radius: 50%; border: 1px solid var(--flow); animation: mf-ring 2.2s ease-out infinite; }
@keyframes mf-ring { 0% { transform: scale(1); opacity: .9; } 100% { transform: scale(4.2); opacity: 0; } }
@media (prefers-reduced-motion: reduce) { .mf-node.active .mf-dot::after { animation: none; opacity: 0; } }
.mf-name { font-size: 12px; color: var(--m); }
.mf-soc { color: var(--t); margin-left: 4px; }
.mf-link { flex: 1; min-width: 28px; display: flex; flex-direction: column; align-items: center; }
.mf-watts { height: 19px; font-size: 14px; font-weight: 300; font-variant-numeric: tabular-nums; color: var(--d); white-space: nowrap; }
.mf-link.on .mf-watts { color: var(--flow); }
.mf-line { position: relative; width: 100%; height: 1px; margin-top: 3px; overflow: hidden; background: var(--line); }
.mf-link.on .mf-line::after {
  content: ''; position: absolute; top: 0; bottom: 0; width: 72px; left: -72px;
  background: linear-gradient(90deg, transparent, var(--flow), transparent);
  animation: mf-forward var(--speed, 2.6s) linear infinite;
}
.mf-link.on.reverse .mf-line::after { animation-direction: reverse; }
.mf-dir { margin-top: 8px; font-size: 12px; color: var(--m); min-height: 15px; white-space: nowrap; }
@keyframes mf-forward { to { left: 100%; } }
@media (prefers-reduced-motion: reduce) { .mf-link.on .mf-line::after { animation: none; left: 0; width: 100%; opacity: .6; } }
.mf-link.out .mf-watts { color: var(--c); }
.mf-link.out .mf-line { background: repeating-linear-gradient(90deg, var(--c) 0 4px, transparent 4px 10px); opacity: .75; }
.mf-node.out .mf-dot { background: transparent; box-shadow: inset 0 0 0 1px var(--c); }
.mf-card.stale .mf-diagram { opacity: .4; }
.mf-card.stale .mf-status { color: var(--c); }
.mf-card.light { --t: #17181A; --m: #5E6266; --d: #8f9296; --c: #B23A22; --dot: rgba(0, 0, 0, .3); --line: rgba(0, 0, 0, .16); }

descriptor.controllerScript:
var el, timer, lastTs;
var STALE_SEC = 180, IDLE_W = 2;
var GRID, LOAD;

function last(name) {
    var row = (self.ctx.data || []).filter(function(d) { return d.dataKey && d.dataKey.name === name; })[0];
    var d = row && row.data;
    if (!d || !d.length) { return null; }
    var v = Number(d[d.length - 1][1]);
    if (name === 'es_ongrid_power') { lastTs = d[d.length - 1][0]; }
    return isNaN(v) ? null : v;
}

function setLink(id, watts, reverse, color, label) {
    var link = el.querySelector(id);
    var on = watts !== null && Math.abs(watts) > IDLE_W;
    link.classList.toggle('on', on);
    link.classList.toggle('reverse', on && reverse);
    link.style.setProperty('--flow', color);
    link.querySelector('.mf-watts').textContent = watts === null ? '–' : Math.round(Math.abs(watts)) + ' W';
    link.querySelector('.mf-dir').textContent = on ? label : '';
    // More power, faster pulse.
    link.style.setProperty('--speed', on ? Math.max(.9, 3.2 - Math.abs(watts) / 1000 * 2.3).toFixed(2) + 's' : '3s');
    return on;
}

function setNode(id, active, color) {
    var node = el.querySelector(id);
    node.classList.toggle('active', active);
    node.style.setProperty('--flow', color);
}

function age() {
    if (!lastTs) { return false; }
    var sec = Math.max(0, Math.round((Date.now() - lastTs) / 1000));
    var stale = sec > STALE_SEC;
    el.querySelector('.mf-card').classList.toggle('stale', stale);
    return stale;
}

function render() {
    if (!el) { return; }
    var grid = last('es_ongrid_power'), off = last('es_offgrid_power'), soc = last('es_bat_soc');
    var charging = grid !== null && grid < 0;
    var gridColor = charging ? GRID : LOAD;
    var gridOn = setLink('.mf-grid', grid, !charging, gridColor, charging ? 'Charging' : 'To grid');
    var offOn = setLink('.mf-load', off, false, LOAD, 'To sockets');
    // A full battery on the mains shows 0 W too, so an outage is drawn as a cut link.
    var out = last('mains') === 0 && !gridOn, gridLink = el.querySelector('.mf-grid');
    gridLink.classList.toggle('out', out);
    el.querySelector('.mf-n-grid').classList.toggle('out', out);
    if (out) { gridLink.querySelector('.mf-watts').textContent = 'Off'; }
    setNode('.mf-n-grid', gridOn, gridColor);
    setNode('.mf-n-load', offOn, LOAD);
    setNode('.mf-n-bat', gridOn || offOn, gridOn ? gridColor : LOAD);
    el.querySelector('.mf-soc').textContent = soc === null ? '–' : Math.round(soc) + '%';
    var stale = age();
    el.querySelector('.mf-status').textContent = stale ? 'No fresh data' : gridOn || offOn ? 'Flowing' : 'Idle';
}

self.onInit = function() {
    el = self.ctx.$container[0].querySelector('.mf-root');
    var light = (self.ctx.settings || {}).theme === 'light';
    GRID = light ? '#55595E' : '#C9CDD1';
    LOAD = light ? '#A85A12' : '#E8B170';
    function node(cls, name, extra) {
        return '<div class="mf-node ' + cls + '"><div class="mf-dot"></div><div class="mf-name">' + name + (extra || '') + '</div></div>';
    }
    function link(cls) {
        return '<div class="mf-link ' + cls + '"><div class="mf-watts"></div><div class="mf-line"></div><div class="mf-dir"></div></div>';
    }
    el.innerHTML = '<div class="mf-card' + (light ? ' light' : '') + '"><div class="mf-head"><span class="mf-title">Energy flow</span><span class="mf-status"></span></div>' +
        '<div class="mf-diagram">' + node('mf-n-grid', 'Grid') + link('mf-grid') +
        node('mf-n-bat', 'Battery', '<span class="mf-soc">–</span>') + link('mf-load') +
        node('mf-n-load', 'Sockets') + '</div></div>';
    timer = setInterval(render, 15000);
    render();
};

self.onDataUpdated = render;

self.onDestroy = function() {
    clearInterval(timer);
};

self.typeParameters = function() {
    return { maxDatasources: 1, maxDataKeys: 4, dataKeysOptional: false };
};
